export type Message<Type, Payload> = Payload extends void
  ? {
      type: Type;
    }
  : {
      type: Type;
      payload: Payload;
    };

/**
 * Shape of the `theme.json` file generated by Reshaped.
 * Typed locally because `reshaped/themes` is no longer exported in Reshaped v4.
 * Every group is optional so that partial or unknown themes are skipped instead of crashing the upload.
 */
export type ThemeShadowPart = {
  offsetX: number;
  offsetY: number;
  blurRadius?: number;
  spreadRadius?: number;
  colorToken: string;
  opacity?: number;
};

/** v4 shadow format */
export type ThemeShadow = {
  parts: ThemeShadowPart[];
  dark?: { parts: ThemeShadowPart[] };
};

export type Theme = {
  color?: Record<string, { hex: string; hexDark?: string }>;
  fontFamily?: Record<string, { family: string }>;
  fontWeight?: Record<string, { weight: number }>;
  font?: Record<
    string,
    {
      fontSize: { px: number };
      lineHeight: { px: number };
      fontWeightToken?: string;
      fontFamilyToken?: string;
      letterSpacing?: { px: number };
    }
  >;
  unit?: Record<string, { px: number }>;
  radius?: Record<string, { px: number }>;
  /** v3 themes used an array of parts per shadow, v4 uses ThemeShadow */
  shadow?: Record<string, ThemeShadow | ThemeShadowPart[]>;
  viewport?: Record<string, { minPx?: number; maxPx?: number }>;
  duration?: Record<string, { ms: number }>;
  easing?: Record<string, { x1: number; y1: number; x2: number; y2: number }>;
  zIndex?: Record<string, { level: number }>;
};

export type UploadThemeResult = { error: string } | { issues: string[] };
